test_vsubsws_saturates:
  #_ REGISTER_IN v3 [80000000, 80000001, 7FFFFFFF, 7FFFFFFE]
  #_ REGISTER_IN v4 [00000001, 00000001, FFFFFFFF, FFFFFFFF]
  vsubsws v3, v3, v4
  blr
  #_ REGISTER_OUT v3 [80000000, 80000000, 7FFFFFFF, 7FFFFFFF]
  #_ REGISTER_OUT v4 [00000001, 00000001, FFFFFFFF, FFFFFFFF]

test_vsubsws_mixed:
  #_ REGISTER_IN v3 [40000000, C0000000, 12345678, 87654321]
  #_ REGISTER_IN v4 [C0000000, 40000000, 12345678, 87654321]
  vsubsws v3, v3, v4
  blr
  #_ REGISTER_OUT v3 [7FFFFFFF, 80000000, 00000000, 00000000]
  #_ REGISTER_OUT v4 [C0000000, 40000000, 12345678, 87654321]
